import test from 'node:test';
import assert from 'node:assert/strict';
import { combineWindows } from './windows.mjs';

const examples = [
  ['empty', [], []],
  ['single', [{ start: 2, end: 5 }], [{ start: 2, end: 5 }]],
  ['touching is separate', [{ start: 0, end: 2 }, { start: 2, end: 5 }], [{ start: 0, end: 2 }, { start: 2, end: 5 }]],
  ['overlap merges', [{ start: 0, end: 4 }, { start: 2, end: 5 }], [{ start: 0, end: 5 }]],
  ['contained interval', [{ start: 2, end: 9 }, { start: 3, end: 4 }], [{ start: 2, end: 9 }]],
  ['numeric order', [{ start: 10, end: 12 }, { start: 2, end: 4 }, { start: -4, end: -1 }], [{ start: -4, end: -1 }, { start: 2, end: 4 }, { start: 10, end: 12 }]],
  ['transitive overlap', [{ start: 4, end: 8 }, { start: 0, end: 3 }, { start: 2, end: 5 }], [{ start: 0, end: 8 }]],
  ['touching after overlap', [{ start: 5, end: 7 }, { start: 0, end: 3 }, { start: 2, end: 5 }], [{ start: 0, end: 5 }, { start: 5, end: 7 }]],
  ['identical intervals', [{ start: 1, end: 4 }, { start: 1, end: 4 }], [{ start: 1, end: 4 }]]
];
for (const [name, source, expected] of examples) {
  test(name, () => {
    const input = structuredClone(source);
    const before = structuredClone(input);
    assert.deepEqual(combineWindows(input), expected);
    assert.deepEqual(input, before, 'must not mutate caller input');
  });
}
test('frozen valid input remains supported', () => {
  const input = Object.freeze([
    Object.freeze({ start: 3, end: 6 }),
    Object.freeze({ start: 1, end: 4 })
  ]);
  assert.deepEqual(combineWindows(input), [{ start: 1, end: 6 }]);
});
